package cljl.lang;

import cljl.Keyword;
import cljl.RT;
import java.util.*;

/**
 * Base class for defrecord runtime instances. Subclasses generated by TypeFactory hold typed fields
 * plus optional metadata and extension map.
 */
public abstract class PersistentRecord implements IPersistentMap, IObj, Map<Object, Object>, Iterable<Map.Entry<Object, Object>> {

    public final PersistentHashMap __meta;
    public final PersistentHashMap __extmap;

    protected PersistentRecord(PersistentHashMap meta, PersistentHashMap extmap) {
        this.__meta = meta;
        this.__extmap = extmap != null ? extmap : PersistentHashMap.EMPTY;
    }

    public abstract Object[] __baseKeys();
    protected abstract int __fieldIndex(Object key);
    protected abstract Object __fieldValue(int idx);
    protected abstract PersistentRecord __withField(int idx, Object val);
    protected abstract PersistentRecord __withExt(PersistentHashMap meta, PersistentHashMap ext);

    @Override
    public PersistentHashMap meta() {
        return __meta;
    }

    @Override
    public PersistentRecord withMeta(PersistentHashMap m) {
        return m == __meta ? this : __withExt(m, __extmap);
    }

    @Override
    public boolean containsKey(Object key) {
        return __fieldIndex(key) >= 0 || __extmap.containsKey(key);
    }

    @Override
    public Object valAt(Object key) {
        return valAt(key, null);
    }

    @Override
    public Object valAt(Object key, Object notFound) {
        int idx = __fieldIndex(key);
        if (idx >= 0) return __fieldValue(idx);
        return __extmap.valAt(key, notFound);
    }

    public Map.Entry<Object, Object> entryAt(Object key) {
        int idx = __fieldIndex(key);
        if (idx >= 0) return new PersistentHashMap.MapEntry(key, __fieldValue(idx));
        return __extmap.entryAt(key);
    }

    @Override
    public Associative assoc(Object key, Object val) {
        int idx = __fieldIndex(key);
        if (idx >= 0) return __withField(idx, val);
        return __withExt(__meta, __extmap.assoc(key, val));
    }

    public Object without(Object key) {
        int idx = __fieldIndex(key);
        if (idx >= 0) {
            Object[] base = __baseKeys();
            PersistentHashMap m = __extmap;
            for (int i = 0; i < base.length; i++) {
                if (i != idx) m = m.assoc(base[i], __fieldValue(i));
            }
            return m.withMeta(__meta);
        }
        PersistentHashMap newExt = __extmap.without(key);
        return newExt == __extmap ? this : __withExt(__meta, newExt);
    }

    @Override
    public int count() {
        return __baseKeys().length + __extmap.count();
    }

    @Override
    public ISeq seq() {
        Object[] base = __baseKeys();
        List<Object> entries = new ArrayList<>(base.length + __extmap.count());
        for (int i = 0; i < base.length; i++) {
            entries.add(new PersistentHashMap.MapEntry(base[i], __fieldValue(i)));
        }
        for (ISeq s = __extmap.seq(); s != null; s = s.next()) {
            entries.add(s.first());
        }
        return entries.isEmpty() ? null : PersistentList.create(entries);
    }

    // Map<Object, Object>
    @Override public int size() { return count(); }
    @Override public boolean isEmpty() { return count() == 0; }
    @Override public Object get(Object key) { return valAt(key); }
    @Override public boolean containsValue(Object value) {
        for (Entry<Object, Object> e : this) {
            if (RT.equiv(e.getValue(), value)) return true;
        }
        return false;
    }
    @Override public Object put(Object key, Object value) { throw new UnsupportedOperationException(); }
    @Override public Object remove(Object key) { throw new UnsupportedOperationException(); }
    @Override public void putAll(Map<?, ?> m) { throw new UnsupportedOperationException(); }
    @Override public void clear() { throw new UnsupportedOperationException(); }
    @Override public Set<Object> keySet() {
        Set<Object> s = new LinkedHashSet<>();
        for (Entry<Object, Object> e : this) s.add(e.getKey());
        return Collections.unmodifiableSet(s);
    }
    @Override public Collection<Object> values() {
        List<Object> vs = new ArrayList<>();
        for (Entry<Object, Object> e : this) vs.add(e.getValue());
        return Collections.unmodifiableList(vs);
    }
    @Override public Set<Entry<Object, Object>> entrySet() {
        return new AbstractSet<>() {
            @Override public Iterator<Entry<Object, Object>> iterator() { return PersistentRecord.this.iterator(); }
            @Override public int size() { return count(); }
        };
    }

    @Override
    @SuppressWarnings("unchecked")
    public Iterator<Entry<Object, Object>> iterator() {
        return new Iterator<>() {
            ISeq s = seq();
            @Override public boolean hasNext() { return s != null; }
            @Override public Entry<Object, Object> next() {
                if (s == null) throw new NoSuchElementException();
                Entry<Object, Object> e = (Entry<Object, Object>) s.first();
                s = s.next();
                return e;
            }
        };
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        PersistentRecord other = (PersistentRecord) o;
        if (count() != other.count()) return false;
        for (Entry<Object, Object> e : this) {
            Object k = e.getKey();
            if (!other.containsKey(k) || !RT.equiv(e.getValue(), other.valAt(k))) return false;
        }
        return true;
    }

    @Override
    public int hashCode() {
        int h = 0;
        for (Entry<Object, Object> e : this) {
            int kh = RT.hash(e.getKey());
            int vh = RT.hash(e.getValue());
            h += (kh ^ vh);
        }
        return h;
    }

    @Override
    public String toString() {
        return "#" + getClass().getName() + RT.printString(PersistentHashMap.createFromMap(this), true);
    }
}
